# Change the sheet's today. Validate first so a bad date is a 400 and writes nothing.
validate:
  class: net.officefloor.hq.app.sheet.ValidateToday
  next: snapshot
# Keep the figures as they were, so the change can audit the ones it moves.
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.sheet.ApplyToday
  govern: [ transaction ]
  next: rollup
# After the change's own lines: a line per person whose figures moved, then the totals if they did.
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithSheet
  govern: [ transaction ]
handle:
  class: net.officefloor.hq.app.sheet.HandleInvalidSheetRequest
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateToday {
    public void validate(@RequestBody TodayRequest request, Out<LocalDate> today, Out<Actor> actor)
            throws InvalidSheetRequestException {
        String raw = request == null || request.today() == null ? "" : request.today().trim();
        try {
            today.set(LocalDate.parse(raw));
            actor.set(new Actor(request.user()));
        } catch (DateTimeParseException e) {
            throw new InvalidSheetRequestException("Not a date (yyyy-mm-dd): " + raw);
        }
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class ApplyToday {
    public void apply(@PathVariable("sheetId") String sheetId, @Val LocalDate today, Sheets sheets) {
        sheets.setToday(sheetId, today);
    }
}
package net.officefloor.hq.app.sheet;

/** Body of a today change: the new date (ISO yyyy-MM-dd) and who makes it. */
public record TodayRequest(String today, String user) {
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { sheetKey, useSheet, type Sheet } from './useSheet';

/** Shows the sheet's today and changes it. */
function SheetToday({ user, sheet }: { user: string; sheet: string }) {
  const queryClient = useQueryClient();
  const { data } = useSheet(sheet);
  const [date, setDate] = useState('');
  const submitOnce = useSubmitOnce();
  const save = useMutation({
    mutationFn: (today: string) =>
      postJson<Sheet>(`/api/sheets/${encodeURIComponent(sheet)}/today`, { today, user }),
    onSuccess: (saved) => queryClient.setQueryData(sheetKey(sheet), saved),
  });

  return (
    <form
      data-testid="sheet-today-form"
      onSubmit={(e) => {
        e.preventDefault();
        submitOnce(() => save.mutateAsync(date.trim()));
      }}
    >
      Today: <strong data-testid="sheet-today">{data?.today ?? ''}</strong>{' '}
      <label>
        Set today{' '}
        <input
          data-testid="sheet-today-input"
          placeholder="yyyy-mm-dd"
          value={date}
          onChange={(e) => {
            setDate(e.target.value);
            save.reset();
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="sheet-today-save" disabled={save.isPending}>
        Save
      </button>
      {save.isError && (
        <span data-testid="sheet-error" role="alert">
          {' '}Could not set today: enter a date as yyyy-mm-dd.
        </span>
      )}
    </form>
  );
}

export const contribution = SheetPanels.fill({ order: 0, Component: SheetToday });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

export type Sheet = { id: string; today: string };

export const sheetKey = (sheet: string) => ['sheet', sheet] as const;

/** The active sheet as the store holds it, re-read whenever the sheet is loaded. */
export function useSheet(sheet: string) {
  return useQuery({
    queryKey: sheetKey(sheet),
    queryFn: () => getJson<Sheet>(`/api/sheets/${encodeURIComponent(sheet)}`),
    staleTime: 0,
    gcTime: 0,
  });
}

/**
 * The sheet's today (yyyy-mm-dd). Every date-dependent decision and every default date on the
 * sheet uses this, never the browser's clock. '' until the sheet has loaded.
 */
export function useSheetToday(sheet: string): string {
  return useSheet(sheet).data?.today ?? '';
}

